class Solution {public:vector<vector<int>>solve(int n,vector<vector<int>>edges){vector<vector<int>>a(n),reverse(n),groups;for(auto e:edges){a[e[0]].push_back(e[1]);reverse[e[1]].push_back(e[0]);}vector<bool>seen(n);vector<int>finish;function<void(int)>first=[&](int u){seen[u]=true;for(int v:a[u])if(!seen[v])first(v);finish.push_back(u);};for(int u=0;u<n;u++)if(!seen[u])first(u);fill(seen.begin(),seen.end(),false);function<void(int,vector<int>&)>second=[&](int u,vector<int>&group){seen[u]=true;group.push_back(u);for(int v:reverse[u])if(!seen[v])second(v,group);};for(int i=finish.size()-1;i>=0;i--)if(!seen[finish[i]]){vector<int>group;second(finish[i],group);sort(group.begin(),group.end());groups.push_back(group);}sort(groups.begin(),groups.end());return groups;}};